<?php require_once __DIR__.'/_bootstrap.php'; $db=getDB();$club=$_SESSION['club_id'];$q=$db->prepare("SELECT t.id,t.table_number,t.table_name,t.table_type,t.status,t.rate_plan_id,rp.plan_name rate_plan_name,rp.rate_per_minute,rp.rate_per_frame,rp.slab_config,s.id session_id,s.player_name_walkin,s.start_time,s.total_pause_seconds,s.billing_type,s.frames_played,s.challenge_amount,s.cafe_amount,p.name player_name,p.tier player_tier FROM tables t LEFT JOIN rate_plans rp ON rp.id=t.rate_plan_id LEFT JOIN sessions s ON s.table_id=t.id AND s.status IN ('running','paused','held') LEFT JOIN players p ON p.id=s.player_id WHERE t.club_id=? AND t.is_active=1 ORDER BY CAST(t.table_number AS UNSIGNED),t.table_number");$q->execute([$club]);$tables=$q->fetchAll();foreach($tables as &$t){$elapsed=$t['start_time']?max(0,time()-strtotime($t['start_time'])-(int)$t['total_pause_seconds']):0;$minutes=$elapsed/60;$amount=0;if($t['billing_type']==='per_minute')$amount=$minutes*(float)$t['rate_per_minute'];elseif($t['billing_type']==='per_frame')$amount=(int)$t['frames_played']*(float)$t['rate_per_frame'];elseif($t['billing_type']==='slab')$amount=calculateSlabBilling($minutes,$t['slab_config']);elseif($t['billing_type']==='challenge')$amount=(float)$t['challenge_amount'];$t['start_time_unix']=$t['start_time']?strtotime($t['start_time']):null;$t['display_amount']=round($amount+(float)$t['cafe_amount']);$t['display_amount_formatted']=money($t['display_amount']);}$stats=['running'=>0,'available'=>0,'held'=>0,'today_revenue'=>0];foreach($tables as $t){if(isset($stats[$t['status']]))$stats[$t['status']]++;}$r=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sessions WHERE club_id=? AND status='completed' AND DATE(end_time)=CURDATE()");$r->execute([$club]);$stats['today_revenue']=(float)$r->fetchColumn();$stats['today_revenue_formatted']=money($stats['today_revenue']);jsonResponse(true,'',compact('tables','stats'));
